def icon(name, cls=""):
    """Render a Lucide icon exactly like lucide-react does (24x24, stroke 2, round caps)."""
    inner = ICONS[name]
    classes = f"lucide lucide-{name} {cls}".strip()
    return Markup(
        '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" '
        'fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" '
        f'stroke-linejoin="round" class="{classes}" aria-hidden="true">{inner}</svg>'
    )
